import * as React from "react";
import { useTranslation } from "gatsby-plugin-react-i18next";
import images from "../images";
import { IndustryItem } from "../interfaces";
import  data  from "../data/data.json";

const IndustryGrid: React.FC = () => {
  const { t } = useTranslation();
  const sections = t("industry.sections", {
    returnObjects: true,
  }) as IndustryItem[];

  return (
    <>
      {sections.map((section: any, index: number) => {
        const isEven = index % 2 === 0;
        const imageData = images[section.image] || {};
        const isGeneral = section.name === "General";
        const isLast = index === sections.length - 1;
        return (
          <section className={`space-y-32 py-16 ${
            !isLast ? "border-b border-Tofu/20" : ""
          }`} id={data.submenu[index]}
          key={section.name || index}
          >
            <div
              
              className={`flex flex-col sm:flex-row ${ isEven ? "" : "sm:flex-row-reverse"}  gap-12 sm:gap-24`}
            >
              {/* Image */}
              <div className="w-[calc(100%+40px)] sm:w-3/4 -ml-[20px] sm:-ml-0">
                <img src={imageData.src} alt={imageData.alt || section.name} className="w-full h-auto" />
              </div>

              {/* Content */}
              <div className="w-full sm:w-1/4 text-Tofu">
                <h2 className="head-3 uppercase mb-5">{section.name}</h2>

                {!isGeneral && (
                  <>
                    {section.description && (
                      <p className="body-3 mb-5">{section.description}</p>
                    )}
                    {section.itemsTitle && section.items && (
                      <>
                        <h4 className="head-7">{section.itemsTitle}</h4>
                        <ul className="list-disc list-outside mx-4 sm:mx-0">
                          {section.items.map(
                            (item: { list: string }, idx: number) => (
                              <li key={idx} className="body-4 ">{item.list}</li>
                            )
                          )}
                        </ul>
                      </>
                    )}
                  </>
                )}

                {/* Custom layout for "General" */}
                {isGeneral && Array.isArray(section.items) && (
                  <div className="mb-5">
                    {section.items.map(
                      (
                        item: { title?: string; text?: string; list?: string },
                        idx: number
                      ) => {
                        if ("title" in item && "text" in item) {
                          interface GeneralItem {
                            title: string;
                            text: string;
                          }
                          const generalItem = item as GeneralItem;
                          return (
                            <div className="mb-5" key={idx}>
                              <h4 className="head-4 uppercase">
                                {generalItem.title}
                              </h4>
                              <p className="body-3">
                                {generalItem.text}
                              </p>
                            </div>
                          );
                        }
                        return null;
                      }
                    )}
                  </div>
                )}
              </div>
            </div>
          </section>
        );
      })}
    </>
  );
};

export default IndustryGrid;
